# src/neural/quantum.cr
require "math"

struct Planet
  property degree : Float64
  property influence : Float64

  def initialize(@degree : Float64, @influence : Float64)
  end

  def angular_distance(other : Planet) : Float64
    Math.min((degree - other.degree).abs, 360.0 - (degree - other.degree).abs)
  end
end

class BirthChart
  property planets : Array(Planet)

  def initialize
    @planets = [
      Planet.new(25.52, 1.0),  # Sun
      Planet.new(18.58, 0.8),  # Moon  
      Planet.new(15.27, 0.6),  # Mercury
      Planet.new(23.29, 0.7),  # Venus
      Planet.new(26.31, 0.9),  # Mars
      Planet.new(8.14, 0.5),   # Jupiter
      Planet.new(24.35, 0.4),  # Saturn
      Planet.new(1.42, 0.3),   # Uranus
      Planet.new(12.54, 0.2),  # Neptune
      Planet.new(0.05, 0.1)    # North Node
    ]
  end

  def synastry_correlation(other : BirthChart) : Float64
    correlation = 0.0
    orbs = [6.90, 2.38, 0.65, 1.29, 5.83, 0.98, 7.55, 1.27, 5.61, 2.27]

    planets.each_with_index do |planet, i|
      other_planet = other.planets[i]
      distance = planet.angular_distance(other_planet)

      if distance <= orbs[i]
        aspect_strength = Math.sin(distance * Math::PI / 180.0)
        correlation += aspect_strength * planet.influence * other_planet.influence
      end
    end

    correlation / planets.size
  end
end

class QuantumNeuron
  property potential : Float64
  property threshold : Float64
  property quantum_phase : Float64
  property birth_chart : BirthChart

  def initialize(@threshold : Float64 = 36.0)
    @potential = 0.0
    @quantum_phase = 0.0
    @birth_chart = BirthChart.new
  end

  def receive_input(input : Float64, time_factor : Float64) : Bool
    astrological_influence = calculate_astrological_influence(time_factor)
    @potential += input * astrological_influence

    if @potential > @threshold
      fire_spike
      @potential = 0.0
      true
    else
      false
    end
  end

  private def calculate_astrological_influence(time_factor : Float64) : Float64
    @quantum_phase += time_factor * Math::PI / 180.0

    influence = 0.0
    @birth_chart.planets.each do |planet|
      planetary_phase = planet.degree * Math::PI / 180.0 + @quantum_phase
      influence += Math.sin(planetary_phase) * planet.influence
    end

    Math.max(0.1, influence / @birth_chart.planets.size)
  end

  private def fire_spike
    puts "Quantum spike fired! Phase: #{@quantum_phase}, Potential: #{@potential}"
  end
end
